sys_variable_value.value:
(function execute(inputs, outputs) {
var inputsPayload = {};

var limit = inputs.limit;
if(limit.trim() === "") limit = 300;
// text is a input of type: string
inputsPayload['port'] = inputs.port;
inputsPayload['port_limit'] = limit;

var capabilityId = '273e4703473262d0873506f1d16d4392'; 
var request = {
	executionRequests: [{
		payload: inputsPayload,
		capabilityId: capabilityId,
		meta: {
			skillConfigId: '3b3ecfcb473262d0873506f1d16d43e4'
		}
	}], 
	mode: 'sync' 
};

try {
	var output = sn_one_extend.OneExtendUtil.execute(request)['capabilities'][request.executionRequests[0].capabilityId]['response'];
	outputs.results = JSON.parse(output).model_output.replace(/[\s\u200B-\u200D\uFEFF]+$/g, '');
} catch(e) {
	outputs.results = 'Something went wrong while executing skill.' + e;
}
})(inputs, outputs);

